sys_script_include.script:
var AgenticBusinessProcessConsultantClientAPI = Class.create();
AgenticBusinessProcessConsultantClientAPI.prototype = Object.extendsObject(global.AbstractAjaxProcessor,
{
	StartInterview: function()
	{
		var GetStringValue = x_snc_devtools.GetStringValue;

		var strBusinessProcessSysId = GetStringValue(this.getParameter('sysparm_business_process_sys_id'));
		var strUserSysId = gs.getUserID();

		var strConversationId = StartInterview(strBusinessProcessSysId, strUserSysId);

		return strConversationId;
	},

    type: 'AgenticBusinessProcessConsultantClientAPI'
});
